entries[53556] = { ["name"] = "Erleuchtete Richturteile", ["text"] = "Gewährt Euch Trefferwertung in Höhe von 50% aller durch Gegenstände oder Effekte erhaltenen Willenskraft und erhöht die Reichweite Eures Zaubers 'Richturteil' um 5 Meter. Zudem heilt Euch Euer Zauber 'Richturteil' sofort um 1279 ." }
