entries[53563] = { ["name"] = "Flamme des Glaubens", ["text"] = "6% von Grundmana 60 Meter Reichweite\nSofort\nDas Ziel wird für alle befreundeten Ziele in einem Radius von 60 Metern zu einer Flamme des Glaubens. Wenn Ihr Ziele mit Euren Zaubern 'Wort der Herrlichkeit', 'Heiliger Schock', 'Lichtblitz', 'Göttliches Licht' oder 'Licht der Morgendämmerung' heilt, wird die Flamme ebenfalls um 50% des geheilten Wertes geheilt. Heilungen durch 'Heiliges Licht' heilen die Flamme um 100% des Wertes. Es kann immer nur ein Ziel zur gleichen Zeit eine Flamme des Glaubens sein. Hält 5 Min. lang an." }
entries[53569] = { ["name"] = "Lichtenergie", ["text"] = "Erhöht die Chance für kritischen Effekt Eures Zaubers 'Heiliger Schock' um 5%. Darüber hinaus verringern Eure kritischen Effekte von 'Heiliger Schock' die Zauberzeit Eures nächsten Zaubers des Typs 'Lichtblitz', 'Heiliges Licht', 'Göttliches Licht' oder 'Heiliges Strahlen' um 1,2 Sek." }
entries[53570] = { ["name"] = "Zehrende Kälte", ["text"] = "10 Meter Reichweite\nSofort\nEntfesselt alle verfügbare Runenmacht, um der Erde unter dem Todesritter jegliche Wärme zu entziehen. Feinde innerhalb von 10 Metern werden in Eis eingeschlossen, das für 1 Sek. pro 5 Runenmacht jegliche ihrer Aktionen verhindert. Feinde zählen als eingefroren, jeglicher verursachte Schaden unterbricht den Effekt." }
entries[53576] = { ["name"] = "Lichtenergie", ["text"] = "Erhöht die Chance für kritischen Effekt Eures Zaubers 'Heiliger Schock' um 10%. Darüber hinaus verringern Eure kritischen Effekte von 'Heiliger Schock' die Zauberzeit Eures nächsten Zaubers des Typs 'Lichtblitz', 'Heiliges Licht', 'Göttliches Licht' oder 'Heiliges Strahlen' um 2,2 Sek." }
entries[53592] = { ["name"] = "Vom Licht berührt", ["text"] = "Erhöht Eure gesamte Ausdauer um 15% und Eure Zaubertrefferchance um 8%. Zudem wird Eure Zaubermacht um einen Wert erhöht, der 60% Eurer Stärke entspricht.\n(Procchance: 10%)" }
entries[53595] = { ["name"] = "Hammer der Rechtschaffenen", ["text"] = "10% von Grundmana Nahkampfreichweite\nSofort 4.5 sek. Abklingzeit\nBenötigt Einhändige Nahkampfwaffe\nTrifft das aktuelle Ziel für 30% Waffenschaden und verursacht eine Welle des Lichts, die allen Zielen im Umkreis von 8 Metern 699 Heiligschaden zufügt. Gewährt eine Aufladung Heiliger Kraft." }
