entries[53600] = { ["name"] = "Schild der Rechtschaffenen", ["text"] = "1 Heilige Kraft Nahkampfreichweite\nSpontanzauber\nVerpasst dem Ziel einen heftigen Schlag mit Eurem Schild und verursacht Heiligschaden. Verbraucht alle Aufladungen Heilige Kraft, um die Schadenshöhe zu bestimmen:\n\n1 Heilige Kraft: ( 585 - 1) Schaden\n2 Heilige Kraft: ( 585 * 3 - 3) Schaden\n3 Heilige Kraft: ( 585 * 6 - 6) Schaden" }
